import { franziAnswer, startFranziAI, franziReady, campusAnswer } from './franzi.js';
import { icon } from './icons.js';
import { DEMO_USER, DEMO_PROFILES, PEOPLE, SPOTS, demoPosts } from './data.js';
import { createDemoWorld, emptyDemoAccount, demoPerson, hydrateDemoPosts, visibleDemoChats } from './demo.js';
import { api, configured } from './api.js';
import { escapeHtml as e, safeImage, initials, dateLabel, timeLabel, relative, filterPosts, validatePost, makeICS, readLocal, saveLocal, TYPES, CATEGORIES } from './core.js';
const $ = s => document.querySelector(s);
const demoWorld=createDemoWorld(readLocal('fhv-demo-v2',null),readLocal('fhv-demo-v1',null));
let activeDemoId;try{activeDemoId=sessionStorage.getItem('fhv-demo-active');}catch{}
if(!demoWorld.profiles.some(p=>p.id===activeDemoId))activeDemoId=demoWorld.profiles[0].id;
const demoAccount=demoWorld.accounts[activeDemoId]||emptyDemoAccount();
const state = {mode:'demo',user:{...demoPerson(demoWorld,activeDemoId)},posts:hydrateDemoPosts(demoWorld),joined:demoAccount.joined,saved:demoAccount.saved,liked:demoAccount.liked,comments:demoWorld.comments,chats:demoWorld.chats,messages:demoWorld.messages,invitations:demoAccount.invitations,tab:['feed','trade','activities','profile'].includes(location.hash.slice(1))?location.hash.slice(1):'feed',filter:'All',query:'',activityTab:'Discover',overlay:null,selected:null,busy:false,loading:false,authMode:'login',createType:'activity',createCategory:'Campus',currentChat:null,noticeRead:false};
let deferredInstall, chatInterval, lastFocus;
const fhvMark = `<svg viewBox="0 0 460 460" fill="currentColor" aria-hidden="true"><path d="M10.8 346.8h337.5V234.3H10.8V121.7h337.6V9.1H461v450.2H10.9l-.1-112.5z"/></svg>`;
const logo = `<span class="wordmark" role="img" aria-label="FHV Friends"><span class="logo-eyebrow">FHV</span><span class="logo-name">${fhvMark}<span>riends<span class="logo-dot">.</span></span></span></span>`;
const avatar = (person,size='') => `<span class="avatar ${person?.color||'blue'} ${size}" aria-hidden="true">${safeImage(person?.avatar_data)?`<img src="${e(safeImage(person.avatar_data))}" alt="">`:person?.role==='oh'?'ÖH':e(initials(person?.name))}</span>`;
const isOh = () => ['oh','admin'].includes(state.user?.role);
const isDemo = () => state.mode==='demo';
const joined = id => state.joined.includes(id);
const count = p => p.join_count || 0;
const full = p => p.capacity && count(p)>=p.capacity && !joined(p.id);
const pendingInvites = () => state.invitations.filter(i=>i.status==='pending');
function persist(){
 if(!isDemo())return;
 demoWorld.profiles=demoWorld.profiles.map(p=>p.id===state.user.id?{...state.user,role:'student'}:p);
 demoWorld.accounts[state.user.id]={joined:state.joined,saved:state.saved,liked:state.liked,invitations:state.invitations};
 demoWorld.posts=state.posts.map(({author,...p})=>p);
 Object.assign(demoWorld,{comments:state.comments,chats:state.chats,messages:state.messages});
 if(!saveLocal('fhv-demo-v2',demoWorld))throw new Error('Device storage is full. Please use a smaller photo.');
 const updated=hydrateDemoPosts(demoWorld);state.posts.forEach(p=>Object.assign(p,updated.find(v=>v.id===p.id)||{}));
}
function toast(message) { $('#toast').textContent=message; $('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500); }
function empty(title,description,action='create',button='Create a post') { return `<div class="empty-state"><span class="empty-icon">${icon('spark',32)}</span><h3>${title}</h3><p>${description}</p>${action?`<button class="btn primary" data-action="${action}">${button}</button>`:''}</div>`; }
function nav() { return `<nav class="bottom-nav" aria-label="Main navigation">${[['feed','home','Feed'],['trade','trade','Trade / Help'],['create','plus','Create'],['activities','calendar','Activities'],['profile','user','Profile']].map(([id,ico,label])=>`<button class="nav-item ${id==='create'?'nav-create':''} ${state.tab===id?'active':''}" ${state.tab===id?'aria-current="page"':''} data-action="${id==='create'?'create':'nav'}" data-tab="${id}" aria-label="${label}"><span class="nav-icon">${icon(ico,id==='create'?29:23,id==='create'?'create-mark':'')}</span><span class="nav-label">${label}</span></button>`).join('')}</nav>`; }
function sidebar(){return `<aside class="sidebar"><button class="brand" data-action="nav" data-tab="feed" aria-label="FHV Friends home">${logo}</button><nav aria-label="Desktop navigation">${[['feed','home','Feed'],['trade','trade','Trade / Help'],['activities','calendar','Activities'],['profile','user','Profile']].map(([id,ico,label])=>`<button class="side-link ${state.tab===id?'active':''}" ${state.tab===id?'aria-current="page"':''} data-action="nav" data-tab="${id}">${icon(ico)}<span>${label}</span></button>`).join('')}<button class="side-link" data-action="people">${icon('people')}<span>Contacts</span></button><button class="side-link" data-action="franzi">${icon('franzi')}<span>Franzi</span></button><button class="side-link" data-action="inbox">${icon('chat')}<span>Messages</span></button></nav><button class="btn primary side-create" data-action="create">${icon('plus',19)} Create post</button><div class="sidebar-bottom">${isDemo()?`<button class="side-user" data-action="test-accounts">${avatar(state.user)}<span><strong>${e(state.user.name)}</strong><small>Switch profile</small></span>${icon('down',16)}</button>`:''}<button class="side-link" data-action="install">${icon('download',18)}<span>Install app</span></button><button class="sidebar-about" data-action="about">About FHV Friends</button></div></aside>`;}
function header(){const title={feed:'Feed',trade:'Trade / Help',activities:'Activities',profile:'Profile'}[state.tab]||'Feed';return `<header class="page-header page-${state.tab}"><div class="mobile-brand">${logo}</div><div class="header-main"><div class="page-title"><span class="page-eyebrow">FHV / COMMUNITY</span><h1>${title}</h1></div><div class="header-actions"><button class="icon-btn franzi-button" data-action="franzi" aria-label="Open Franzi">${icon('franzi',25)}<span class="franzi-dot"></span></button><button class="icon-btn" data-action="inbox" aria-label="Open messages">${icon('chat')}</button><button class="icon-btn notification-btn" data-action="notifications" aria-label="Invitations and updates">${icon('bell')}${!state.noticeRead&&pendingInvites().length?'<span class="notification-dot"></span>':''}</button></div></div></header>`;}
function statusBanner(){return '';}
function chips(items,selected,action='filter') { return `<div class="chips" role="group" aria-label="Filter">${items.map(f=>`<button class="chip ${selected===f?'selected':''}" aria-pressed="${selected===f}" data-action="${action}" data-value="${f}">${f}</button>`).join('')}</div>`; }
function searchBox(placeholder='What are you looking for?') { return `<label class="search-box">${icon('search',20)}<input id="search" type="search" value="${e(state.query)}" placeholder="${placeholder}" aria-label="${placeholder}" autocomplete="off"><kbd>/</kbd></label>`; }
function authorLine(p) { return `<div class="author-line"><button class="person-avatar" data-action="person" data-id="${p.author_id}" aria-label="Profile of ${e(p.author?.name)} open">${avatar(p.author)}</button><div><button class="author-name" data-action="person" data-id="${p.author_id}"><strong>${e(p.author?.name || 'Campus member')}${p.pinned||p.author?.role==='oh'?'<span class="verified" title="Students’ union">'+icon('check',11)+'</span>':''}</strong></button><small>${e(p.author?.course || 'FHV')} · ${relative(p.created_at)}</small></div><button class="icon-btn small card-more" data-action="post-menu" data-id="${p.id}" aria-label="Post options">${icon('more',20)}</button></div>`; }
function bookmarkButton(p) { const saved=state.saved.includes(p.id);return `<button class="icon-btn small ${saved?'is-saved':''}" data-action="save" data-id="${p.id}" aria-label="${saved?'Remove from saved':'Save post'}" aria-pressed="${saved}">${icon('bookmark',19)}</button>`; }
function hero(p){
 return `<article class="pinned-post"><div class="pinned-feature"><div class="pinned-label">${icon('pin',15)} ÖH FHV <span>PINNED</span></div><button class="text-link pinned-title" data-action="detail" data-id="${p.id}"><h2>${e(p.title)}</h2></button><div class="pinned-bottom"><span>${icon('map',15)} ${e(p.location)}</span><button class="btn primary" data-action="detail" data-id="${p.id}">View</button></div></div><button class="feature-date" data-action="detail" data-id="${p.id}" aria-label="${e(p.title)} view"><span>${dateLabel(p.starts_at,{weekday:'short'}).split(',')[0]}</span><strong>${new Date(p.starts_at).getDate()}</strong><small>${dateLabel(p.starts_at,{month:'long'}).replace(/\d+\.?\s*/,'')}</small><span>${timeLabel(p.starts_at)} </span></button></article>`;
}

function miniAvatars(){return '';}
function postCard(p,{compact=false}={}){
 const activity=p.type==='activity',ride=p.category==='Rides',hasPhoto=Boolean(safeImage(p.image_data));
 const tone={activity:({Rides:'green',Culture:'lavender',Campus:'yellow',Sport:'coral'}[p.category]||'blue'),food:'green',trade:'lavender',help:'yellow',life:'coral'}[p.type];
 const label=ride?'Ride':p.type==='trade'?(Number(p.price)>0?'For sale':'Free stuff'):TYPES[p.type];
 const liked=state.liked.includes(p.id),poster=activity&&!hasPhoto;
 const cover=hasPhoto?`<button class="card-visual" data-action="detail" data-id="${p.id}" aria-label="${e(p.title)} view"><img src="${e(safeImage(p.image_data))}" alt="${e(p.title)}" loading="lazy"></button>`:poster?`<button class="event-poster ${tone}" data-action="detail" data-id="${p.id}"><span class="poster-top"><span>${e(ride?'Rides':p.category)}</span><span>${dateLabel(p.starts_at,{weekday:'short'})}</span></span><h3>${e(p.title)}</h3><span class="poster-bottom"><span>${icon(ride?'car':'calendar',18)} ${timeLabel(p.starts_at)} </span>${icon(ride?'car':p.category==='Study'?'book':p.category==='Culture'?'coffee':'people',42)}</span></button>`:'';
 return `<article class="post-card tone-${tone} ${poster?'has-poster':''} ${compact?'compact':''}">${authorLine(p)}${cover}<div class="card-body"><div class="card-kicker"><span class="type-label ${tone}">${e(label)}</span>${p.type==='help'?`<span class="secondary-label">${p.help_direction==='request'?'Looking for help':'Offering help'}</span>`:''}${p.status==='reserved'?'<span class="reserved-label">Reserved</span>':''}</div>${!poster?`<button class="text-link card-title" data-action="detail" data-id="${p.id}"><h3>${e(p.title)}</h3></button>`:''}<p class="card-description">${e(p.description)}</p><div class="card-meta">${icon('map',15)} ${e(p.location)}${ride?`<span class="ride-route">${e(p.ride_destination)} · ${Math.max(0,p.capacity-count(p))} available · ${Number(p.price).toLocaleString('en-GB')} €</span>`:''}</div><div class="card-footer"><button class="like-btn ${liked?'liked':''}" aria-label="Like" aria-pressed="${liked}" data-action="like" data-id="${p.id}">${icon('heart',19)}<span>${Number(p.likes||0)}</span></button>${activity?`<span class="going-label">${count(p)} going</span>`:`<span class="price-label">${p.price?`${Number(p.price).toLocaleString('en-GB')} €`:'Free'}</span>`}<div class="card-footer-right">${bookmarkButton(p)}<button class="btn small ${joined(p.id)?'joined':'soft'}" data-action="detail" data-id="${p.id}">${activity?(joined(p.id)?icon('check',14)+' Going':full(p)?'Full':'Join'):p.type==='help'?'Contact':'View'}</button></div></div></div></article>`;
}

function feed() { const all = filterPosts(state.posts,{tab:'feed',filter:state.filter,query:state.query}); const featured = state.filter==='All'&&!state.query?all.find(p=>p.pinned&&p.type==='activity'):null; const rest=all.filter(p=>p.id!==featured?.id); return `${searchBox('Search campus')}${chips(['All','Activities','For sale','Free stuff','Food','Help','Campus life'],state.filter)}<div id="feed-results">${featured?hero(featured):''}<div class="section-heading"><h2>${state.query?'Search results':state.filter==='All'?'Posts':state.filter}</h2><span>${rest.length} Posts</span></div><div class="post-grid">${rest.length?rest.map(p=>postCard(p)).join(''):empty('No posts found.','Try another search.')}</div></div>`; }
function trade(){const posts=filterPosts(state.posts,{tab:'trade',filter:state.filter});return `${chips(['All','For sale','Free stuff','Food','Help'],state.filter)}<div class="section-heading"><h2>${state.filter==='All'?'Trade / Help':state.filter}</h2><button class="text-link" data-action="create-trade">${icon('plus',16)} Create post</button></div><div class="post-grid">${posts.length?posts.map(p=>postCard(p)).join(''):empty('No posts yet.','Post something to get started.')}</div>`;}
function invitationCard(inv) { const p=state.posts.find(x=>x.id===inv.post_id);if(!p)return '';const who=p.author?.name||'Campus'; return `<article class="invitation-card ${inv.sender_id==='demo-oh'||p.pinned?'yellow':'lavender'}"><span class="tiny-label">${e(who)} ${p.pinned?'· OFFICIAL':'INVITED YOU'}</span><h3>${e(p.subtitle||p.title)}</h3><p>${dateLabel(p.starts_at,{weekday:'short'})} · ${timeLabel(p.starts_at)}</p><small>${e(p.location)} · ${count(p)} going</small><div class="invitation-actions"><button class="btn primary" data-action="accept" data-id="${inv.id}">${icon('check',16)} Accept invitation</button><button class="btn translucent" data-action="decline" data-id="${inv.id}">Not now</button></div></article>`; }
function activities(){const invites=pendingInvites();const posts=filterPosts(state.posts,{tab:'activities',filter:state.filter,query:state.query,activityTab:state.activityTab,userId:state.user.id,joined:state.joined});return `<div class="segment-control activity-segments">${['Discover','Invitations','My plans'].map(v=>`<button class="${state.activityTab===v?'selected':''}" data-action="activity-tab" data-value="${v}">${v}${v==='Invitations'&&invites.length?`<span class="count-badge">${invites.length}</span>`:''}</button>`).join('')}</div>${state.activityTab==='Invitations'?`<div class="invitation-list">${invites.length?invites.map(invitationCard).join(''):empty('No pending invitations.','',null)}</div>`:`${searchBox('Search activities')}${chips(CATEGORIES,state.filter)}<div class="section-heading"><h2>${state.activityTab==='My plans'?'My plans':'Upcoming activities'}</h2><button class="text-link ride-offer" data-action="create-ride">Offer a ride</button></div><div class="post-grid activity-grid">${posts.length?posts.map(p=>postCard(p)).join(''):empty('No activities yet.','',state.activityTab==='My plans'?'discover':'create',state.activityTab==='My plans'?'Discover':'Create activity')}</div>`}`;}
function profile(){
 const mine=state.posts.filter(p=>p.author_id===state.user.id);
 const entry=(action,label,ico)=>`<button data-action="${action}">${icon(ico,22,'system-icon')}<span class="menu-copy"><strong>${label}</strong></span>${icon('chevron',17,'system-icon')}</button>`;
 return `<section class="profile-card"><div class="profile-content"><div class="profile-heading">${avatar(state.user,'large')}<button class="btn outline small" data-action="edit-profile">Edit profile</button></div><h2>${e(state.user.name)}</h2>${state.user.course?`<p class="profile-course">${e(state.user.course)}</p>`:''}${!isDemo()?`<span class="verified-label">${icon('shield',14,'system-icon')} FHV email verified</span>`:''}${state.user.bio?`<p class="profile-bio">${e(state.user.bio)}</p>`:''}<div class="interest-chips">${(state.user.interests||[]).map(v=>`<span>${e(v)}</span>`).join('')}</div><div class="profile-stats"><div><strong>${state.joined.length}</strong><span>Going</span></div><div><strong>${mine.length}</strong><span>Posts</span></div><div><strong>${state.saved.length}</strong><span>Saved</span></div></div></div></section><section class="menu-section"><h2>Your campus</h2><div class="profile-menu">${entry('people','Contacts','people')}${entry('saved','Saved posts','bookmark')}${entry('my-posts','My posts','user')}</div></section><section class="menu-section"><h2>Settings</h2><div class="profile-menu">${isDemo()?entry('test-accounts','Switch profile','user'):''}${entry('install','Install app','download')}${entry('about','About FHV Friends','shield')}${entry(isDemo()?'auth':'logout',isDemo()?'Sign in with FHV email':'Sign out','logout')}</div></section>`;
}
function rightRail(){return '';}
function render() { $('#app').innerHTML=`<div class="app-shell">${sidebar()}<div class="main-shell">${statusBanner()}<div class="content-layout"><main id="main" tabindex="-1">${header()}<div class="page-content ${state.tab}-page">${state.loading?'<div class="loading-state"><span class="spinner"></span><p>Loading…</p></div>':({feed,trade,activities,profile}[state.tab]||feed)()}</div></main>${state.tab!=='profile'?rightRail():''}</div></div>${nav()}</div>`; }
function navigate(tab) { state.tab=tab;state.filter='All';state.query='';history.replaceState(null,'',`#${tab}`);closeModal();render();window.scrollTo({top:0,behavior:'instant'}); }
function modal(title,body,{wide=false,footer='',label=title,cls=''}={}) { clearInterval(chatInterval); lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal ${wide?'wide':''} ${cls}" role="dialog" aria-modal="true" aria-label="${e(label)}"><div class="modal-handle"></div><header class="modal-header"><h2>${e(title)}</h2><button class="icon-btn" data-action="close" aria-label="Close">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;document.body.classList.add('modal-open');$('#overlay').querySelector('button,input,textarea,select')?.focus(); }
function closeModal() { if(state.overlay==='create'&&!state.editingId)saveDraft(false);clearInterval(chatInterval);state.overlay=null;state.selected=null;state.currentChat=null;$('#overlay').innerHTML='';document.body.classList.remove('modal-open');lastFocus?.isConnected&&lastFocus.focus(); }
async function detail(id) { const p=state.posts.find(x=>x.id===id);if(!p)return;state.overlay='detail';state.selected=id;const activity=p.type==='activity';const own=p.author_id===state.user.id; const expired=activity&&new Date(p.starts_at)<new Date();const content=`${safeImage(p.image_data)?`<div class="detail-art"><img src="${e(safeImage(p.image_data))}" alt="${e(p.title)}"><span class="detail-category ${activity?'blue':p.type==='help'?'yellow':'lavender'}">${e(activity?p.category:TYPES[p.type])}</span></div>`:''}<div class="detail-content"><div class="detail-topline">${authorLine(p)}${bookmarkButton(p)}</div><h2 class="detail-title">${e(p.subtitle||p.title)}</h2>${activity?`<div class="detail-date"><span class="date-block"><strong>${new Date(p.starts_at).getDate()}</strong><small>${dateLabel(p.starts_at,{month:'short'}).replace(/\d+\.?\s*/,'')}</small></span><div><strong>${dateLabel(p.starts_at,{weekday:'long',year:'numeric'})}</strong><span>${timeLabel(p.starts_at)}  · ${p.price?`${p.price} €`:'Free'}</span><span>${icon('map',13)} ${e(p.location)}</span></div><button class="icon-btn" data-action="calendar" data-id="${p.id}" aria-label="Add to calendar">${icon('calendar',21)}</button></div>`:`<div class="detail-listing-meta"><span>${icon('map',17)} ${e(p.location)}</span><strong>${p.price?`${p.price} €`:'Free'}</strong></div>`}${p.category==='Rides'?`<div class="ride-detail">${icon('car',24)}<div><strong>${e(p.location)} → ${e(p.ride_destination)}</strong><p>${Math.max(0,p.capacity-count(p))} seats available · ${Number(p.price).toLocaleString('en-GB')} € per person</p></div></div>`:''}<p class="detail-description">${e(p.description).replace(/\n/g,'<br>')}</p>${p.type==='food'?'<div class="info-box"><span>'+icon('leaf',22)+'</span><div><strong>Meet in person.</strong><p>Check ingredients, allergens and pickup time with the person sharing food.</p></div></div>':''}${activity?`<div class="detail-attendees yellow"><div>${miniAvatars()}<strong>${count(p)} ${count(p)===1?'student is':'students are'} going</strong></div><p>${p.capacity?`${Math.max(0,p.capacity-count(p))} of ${p.capacity} places available.`:''}</p></div>${own?'<div class="host-actions"><button class="btn outline full" data-action="invite-people" data-id="'+p.id+'">'+icon('people',18)+' Invite people</button><button class="btn soft full" data-action="group-chat" data-id="'+p.id+'">'+icon('chat',18)+' Open group chat</button></div>':''}${joined(p.id)?`<div class="joined-note">${icon('check',18)} You’re going.</div><div class="detail-secondary-actions"><button class="text-link" data-action="group-chat" data-id="${p.id}">${icon('chat',16)} Group chat</button><button class="text-link danger" data-action="join" data-id="${p.id}">Leave activity</button></div>`:''}`:''}<section class="comments-section"><h3>Comments <span id="comment-count"></span></h3><div id="comments-list"><p class="muted">${isDemo()?'No comments yet.':'Loading comments…'}</p></div><form id="comment-form" data-post="${p.id}" class="comment-form"><input name="body" required minlength="1" maxlength="1000" placeholder="Write a comment…" aria-label="Write a comment"><button class="icon-btn dark" type="submit" aria-label="Send comment">${icon('send',18)}</button></form></section></div>`;
modal('Details',content,{wide:true,cls:'detail-modal',footer:`<div class="detail-footer-copy"><strong>${activity?(expired?'Activity ended':full(p)?'Fully booked':'${FREE}'):p.status==='reserved'?'Bereits reserviert':p.price?`${p.price} €`:'Free'}</strong><span>${e(p.location)}</span></div><button class="btn primary" data-action="${own?'share':activity?'join':'contact'}" data-id="${p.id}" ${expired||full(p)?'disabled':''}>${own?icon('share',17)+' Teilen':activity?(joined(p.id)?icon('check',17)+' You’re going':'Join activity'):(p.type==='help'?'Write a message':'Get in touch')}</button>`.replace('${FREE}',p.price?`${p.price} €`:'Free')});
loadComments(id);
}
async function loadComments(id) { try { const comments = isDemo()?(state.comments[id]||[]):await api.comments(id);if(state.selected!==id)return;$('#comments-list').innerHTML=comments.length?comments.map(c=>`<div class="comment">${avatar(isDemo()?demoPerson(demoWorld,c.author_id||c.author?.id):c.author||state.user,'mini')}<div><strong>${e(isDemo()?demoPerson(demoWorld,c.author_id||c.author?.id).name:c.author?.name||state.user.name)} <small>${relative(c.created_at)}</small></strong><p>${e(c.body)}</p></div></div>`).join(''):'<p class="muted">No comments yet.</p>';$('#comment-count').textContent=comments.length||'';}catch{if($('#comments-list'))$('#comments-list').innerHTML='<p class="muted">Could not load comments.</p>';} }
function createModal(type=state.createType,editingId=null,ride=false) { state.overlay='create';state.createType=type;state.editingId=editingId;state.postPhotoDraft=null;const editing=state.posts.find(p=>p.id===editingId);const draft=editing?{...editing,date:editing.starts_at?new Date(new Date(editing.starts_at).getTime()-new Date(editing.starts_at).getTimezoneOffset()*60000).toISOString().slice(0,10):'',time:editing.starts_at?timeLabel(editing.starts_at):''}:readLocal('fhv-draft',{});if(ride)draft.category='Rides';if(!draft.category)draft.category=type==='help'?'Study':type==='food'?'Food':'Campus';const title=type==='activity'?'Activity':type==='help'?'Help & tutoring':TYPES[type];const tomorrow=new Date(Date.now()+86400000); const date=new Date(tomorrow.getTime()-tomorrow.getTimezoneOffset()*60000).toISOString().slice(0,10);modal(editing?'Edit post':'Create a post',`<div class="create-intro"><h2>${title}</h2></div><div class="create-types">${Object.entries(TYPES).map(([key,label])=>`<button type="button" class="type-option ${state.createType===key?'selected':''}" data-action="create-type" data-value="${key}" ${editing?'disabled':''}>${icon({activity:'calendar',trade:'trade',food:'leaf',help:'book',life:'people'}[key],18)} ${label}</button>`).join('')}<button type="button" class="type-option ${draft.category==='Rides'?'selected':''}" data-action="create-ride" ${editing?'disabled':''}>${icon('car',18)} Ride</button></div><form id="create-form"><input type="hidden" name="type" value="${type}"><label>Title<input name="title" required minlength="4" maxlength="100" value="${e(draft.type===type?draft.title||'':'')}" placeholder="${({activity:'For example: Bouldering tomorrow?',trade:'For example: Skis, 170 cm, €45',food:'For example: One extra portion of pasta',help:'For example: Help with engineering mechanics',life:'What would you like to share?'})[type]}"></label><label>Description<textarea name="description" required minlength="10" maxlength="3000" rows="4" placeholder="What should people know?">${e(draft.type===type?draft.description||'':'')}</textarea></label>${imageEditor('post',draft.image_data)}${type==='activity'?`<div class="form-row"><label>Date<input type="date" name="date" min="${date}" value="${draft.type===type&&draft.date>=date?draft.date:date}" required></label><label>Time<input type="time" name="time" value="${e(draft.type===type?draft.time||'18:00':'18:00')}" required></label></div>`:''}<label>${type==='activity'?'Meeting point':'Pickup / location'}<input name="location" list="campus-spots" maxlength="150" required placeholder="Choose a campus spot or enter a location" value="${e(draft.type===type?draft.location||'':'')}"><datalist id="campus-spots">${SPOTS.map(s=>`<option value="${s.name} · FHV">`).join('')}<option value="By arrangement"></datalist></label>${type==='activity'?`<div id="ride-fields" ${draft.category==='Rides'?'':'hidden'}><label>Destination<input name="ride_destination" maxlength="150" value="${e(draft.ride_destination||'')}" placeholder="For example: Bregenz station" ${draft.category==='Rides'?'required':'disabled'}></label><label>Contribution per person (€)<input name="price" type="number" min="0" max="10000" step="0.01" value="${Number(draft.price||0)}" ${draft.category==='Rides'?'':'disabled'}></label></div>`:''}<div class="form-row"><label>Category<select name="category">${CATEGORIES.filter(x=>x!=='All'&&(type==='activity'||x!=='Rides')).map(c=>`<option ${draft.category===c?'selected':''}>${c}</option>`).join('')}</select></label>${type==='activity'?`<label>${draft.category==='Rides'?'Available seats':'Capacity'}<input type="number" name="capacity" min="${draft.category==='Rides'?1:2}" max="${draft.category==='Rides'?8:500}" placeholder="No limit" value="${e(draft.capacity||'')}"></label>`:type==='trade'||type==='help'?`<label>Price (€) · 0 = free<input type="number" name="price" min="0" max="10000" step="0.01" value="${Number(draft.price||0)}"></label>`:''}</div>${type==='help'?'<label>You would like to…<select name="help_direction"><option value="offer">Offer help</option><option value="request">Ask for help</option></select></label>':''}${type==='food'?'<div class="info-box">'+icon('leaf',20)+'<p>Include ingredients and allergens. Arrange a handover in person.</p></div>':''}${isOh()?'<label class="check-label"><input type="checkbox" name="pinned"> Post as the students’ union and pin to the feed</label>':''}<div class="form-error" id="create-error" role="alert"></div><div class="publishing-as">${avatar(state.user,'mini')}<span>As <strong>${e(state.user.name)}</strong><small>For the FHV community</small></span><button class="text-link" type="button" data-action="save-draft">Save draft</button></div><button type="submit" class="btn primary full">${icon('plus',18)} ${editing?'Save changes':isDemo()?'Publish post':'Publish'}</button></form>`,{wide:true,cls:'create-modal'});state.postPhotoDraft=draft.image_data||null;if(editing){const help=$('[name=help_direction]');if(help)help.value=editing.help_direction||'offer';const pin=$('[name=pinned]');if(pin)pin.checked=editing.pinned;} }
function authModal(mode='login') { state.overlay='auth';state.authMode=mode;modal('',`<div class="auth-brand">${logo}</div><h2>${mode==='signup'?'Create account':'Sign in'}</h2><p>Use your verified FHV email.</p><div class="segment-control"><button class="${mode==='login'?'selected':''}" data-action="auth-mode" data-value="login">Sign in</button><button class="${mode==='signup'?'selected':''}" data-action="auth-mode" data-value="signup">Create account</button></div><form id="auth-form">${mode==='signup'?'<label>Your name<input name="name" autocomplete="name" placeholder="What’s your name?" required minlength="2" maxlength="80"></label>':''}<label>FHV email<input type="email" name="email" autocomplete="email" placeholder="vorname.nachname@students.fhv.at" required></label><label>Password<input name="password" type="password" autocomplete="${mode==='signup'?'new-password':'current-password'}" minlength="${mode==='signup'?12:1}" required placeholder="${mode==='signup'?'At least 12 characters':'Your password'}"></label>${mode==='signup'?'<p class="form-hint">Check your email to confirm your account before signing in.</p>':''}<div class="form-error" id="auth-error" role="alert"></div>${!configured?'<div class="setup-notice">'+icon('settings',20)+'<span><strong>FHV sign-in is not enabled yet.</strong> Shared accounts are not connected in this presentation.</span></div>':''}<button class="btn primary full" type="submit" ${!configured?'disabled':''}>${mode==='signup'?'Create account':'Sign in with FHV email'}</button></form>${mode==='login'?'<button class="text-link auth-demo" data-action="recover">Forgot password?</button>':''}<div class="auth-secure">${icon('shield',15)} @students.fhv.at & @fhv.at · Email verification required</div><button class="text-link auth-demo" data-action="close">Continue to app</button>`,{cls:'auth-modal'}); }
function editProfile(){state.overlay='edit-profile';state.profilePhotoDraft=state.user.avatar_data||null;modal('Edit profile',`<form id="profile-form">${imageEditor('profile',state.user.avatar_data)}<label>Name<input name="name" value="${e(state.user.name)}" required minlength="2" maxlength="80"></label><label>Degree programme<input name="course" value="${e(state.user.course||'')}" placeholder="For example: Mechatronics · MSc" maxlength="100"></label><label>About me<textarea name="bio" maxlength="400" rows="3" placeholder="Your interests, semester, what you enjoy…">${e(state.user.bio||'')}</textarea></label><label>Interests<input name="interests" maxlength="200" value="${e((state.user.interests||[]).join(', '))}" placeholder="Bouldering, cycling, music"></label><div class="form-error" id="profile-error" role="alert"></div><button type="submit" class="btn primary full">Save</button></form>`);}
function notifications() { state.noticeRead=true;render();state.overlay='notifications';modal('Your invitations',`<p class="modal-lead"></p><div class="notification-list">${pendingInvites().length?pendingInvites().map(invitationCard).join(''):empty('You’re all caught up.','New invitations appear here.',null)}</div>`); }
function savedModal(own=false) { state.overlay=own?'my-posts':'saved';const posts=state.posts.filter(p=>own?p.author_id===state.user.id:state.saved.includes(p.id));modal(own?'Your posts':'Saved posts',`<div class="saved-list">${posts.length?posts.map(p=>`<button class="saved-row" data-action="detail" data-id="${p.id}"><span class="saved-thumb">${safeImage(p.image_data)?`<img src="${e(safeImage(p.image_data))}" alt="">`:icon('calendar',24)}</span><span><small>${e(TYPES[p.type])}</small><strong>${e(p.subtitle||p.title)}</strong><small>${e(p.location)}</small></span>${icon('chevron',17)}</button>`).join(''):empty(own?'No posts yet.':'No saved posts yet.','',own?'create':'close',own?'Create a post':'Explore campus')}</div>`); }
function about(){state.overlay='about';modal('About FHV Friends',`<div class="about-brand">${logo}</div><p>A student-built community for FHV: make plans, share things and help each other out.</p><h3>Data & privacy</h3><p>${isDemo()?'This presentation uses four editable local profiles. Posts, connections and conversations stay in this browser. They are not shared with other devices. FHV sign-in and a shared database are not connected yet.':'You are signed in with your FHV account. Your content is stored in the connected Supabase database.'}</p><p>Franzi’s optional AI runs on your device. Model files are downloaded only when you enable it.</p><h3>About the project</h3><p>FHV Friends is a student project, not an official FHV service. The FHV mark belongs to FH Vorarlberg.</p>${isDemo()?'<button class="btn outline full" data-action="reset-demo">Reset local data</button>':''}`);}
async function toggleSave(id) { const on=!state.saved.includes(id); if(!isDemo())await api.toggle('bookmarks',id,state.user.id,on); state.saved=on?[...state.saved,id]:state.saved.filter(x=>x!==id);persist();render();if(state.overlay==='detail')detail(id);toast(on?'Saved for later.':'Removed from saved posts.'); }
async function toggleLike(id) { const p=state.posts.find(x=>x.id===id);if(!p)return;const on=!state.liked.includes(id);if(!isDemo())await api.toggle('likes',id,state.user.id,on);state.liked=on?[...state.liked,id]:state.liked.filter(x=>x!==id);p.likes=Math.max(0,Number(p.likes||0)+(on?1:-1));persist();render(); }
async function joinActivity(id) { const p=state.posts.find(x=>x.id===id);if(!p||p.type!=='activity')return;const on=!joined(id);if(on&&full(p)){toast('This activity is full.');return;}if(!isDemo())await api.rpc('set_attendance',{activity_id:id,attending:on});state.joined=on?[...state.joined,id]:state.joined.filter(x=>x!==id);p.join_count=Math.max(0,count(p)+(on?1:-1));persist();render();if(state.overlay==='detail')detail(id);toast(on?'You’re going.':'You’ve left the activity.'); }
async function respondInvite(id,status) { const inv=state.invitations.find(x=>x.id===id);if(!inv)return;const p=state.posts.find(x=>x.id===inv.post_id);if(status==='accepted'&&p&&full(p)){toast('This activity is now full.');return;}if(!isDemo())await api.invitationStatus(id,status);if(status==='accepted'&&!joined(inv.post_id)){state.joined.push(inv.post_id);if(p)p.join_count=count(p)+1;}inv.status=status;persist();render();if(state.overlay==='notifications')notifications();toast(status==='accepted'?'Invitation accepted.':'Invitation declined.'); }
async function contact(id){const p=state.posts.find(x=>x.id===id);if(p)await messagePerson(p.author_id);}
async function messagePerson(id){
 if(id===state.user.id)return toast('This is your profile.');
 if(!isDemo())return openChat(await api.rpc('start_direct_chat',{other_user:id}));
 const person=demoPerson(demoWorld,id);let chat=state.chats.find(c=>!c.post_id&&c.members?.includes(state.user.id)&&c.members?.includes(id));
 if(!chat){chat={id:crypto.randomUUID(),members:[state.user.id,id],title:person.name,created_at:new Date().toISOString()};state.chats.push(chat);state.messages[chat.id]=[];persist();}return openChat(chat.id);
}
let connectionRows=[],peopleRows=[];
async function loadPeople(){peopleRows=isDemo()?demoWorld.profiles:await api.people();connectionRows=isDemo()?(demoWorld.connections??=[]):await api.connections();}
const connectionWith=id=>connectionRows.find(c=>(c.sender_id===state.user.id&&c.recipient_id===id)||(c.recipient_id===state.user.id&&c.sender_id===id));
async function people(){
 state.overlay='people';await loadPeople();modal('Contacts',`<div class="people-tabs">${['All','Connected','Requests'].map(v=>`<button class="chip ${state.peopleTab===v?'selected':''}" data-action="people-filter" data-value="${v}">${v}</button>`).join('')}</div><div class="chat-list">${peopleRows.filter(p=>p.id!==state.user.id).filter(p=>{const c=connectionWith(p.id);return state.peopleTab==='Connected'?c?.status==='accepted':state.peopleTab==='Requests'?c?.status==='pending'&&c.recipient_id===state.user.id:true;}).map(p=>{const c=connectionWith(p.id);return `<button class="chat-row" data-action="person" data-id="${p.id}">${avatar(p)}<span><strong>${e(p.name)}</strong><small>${e(c?.status==='accepted'?'Connected':c?.status==='pending'?(c.recipient_id===state.user.id?'Wants to connect':'Request sent'):p.course||'FHV')}</small></span>${icon('chevron',18)}</button>`;}).join('')||'<p class="muted">Nothing here yet.</p>'}</div>`);
}
async function personProfile(id){
 if(id===state.user.id){closeModal();return navigate('profile');}await loadPeople();const p=peopleRows.find(p=>p.id===id)||(isDemo()?demoPerson(demoWorld,id):await api.profile(id));if(!p)return;state.overlay='person';const c=connectionWith(id);modal(p.name,`<div class="person-profile">${avatar(p,'large')}<h2>${e(p.name)}</h2><p class="muted">${e(p.course||'FHV')}</p>${p.bio?`<p>${e(p.bio)}</p>`:''}<div class="interest-chips">${(p.interests||[]).map(x=>`<span>${e(x)}</span>`).join('')}</div></div><div class="person-actions"><button class="btn primary" data-action="message-person" data-id="${id}">${icon('chat',18)} Message</button>${c?.status==='accepted'?`<button class="btn outline" data-action="disconnect" data-id="${id}">Connected · remove</button>`:c?.status==='pending'?(c.recipient_id===state.user.id?`<button class="btn soft" data-action="connect-accept" data-id="${id}">Accept</button><button class="btn outline" data-action="disconnect" data-id="${id}">Decline</button>`:`<button class="btn outline" data-action="disconnect" data-id="${id}">Cancel request</button>`):`<button class="btn soft" data-action="connect" data-id="${id}">Connect</button>`}</div><div class="section-heading"><h2>Posts</h2></div><div class="post-grid">${state.posts.filter(x=>x.author_id===id).map(x=>postCard(x)).join('')||'<p class="muted">No posts yet.</p>'}</div>`);
}
async function changeConnection(id,action){
 await loadPeople();const c=connectionWith(id);
 if(isDemo()){
  if(action==='request'&&!c)demoWorld.connections.push({id:crypto.randomUUID(),sender_id:state.user.id,recipient_id:id,status:'pending'});
  if(action==='accept'&&c?.recipient_id===state.user.id)c.status='accepted';
  if(action==='remove'&&c)demoWorld.connections=demoWorld.connections.filter(x=>x.id!==c.id);persist();
 }else if(action==='request')await api.connect(id);else if(action==='accept'&&c)await api.respondConnection(c.id,true);else if(c)await api.disconnect(c.id);
 await personProfile(id);
}
const franziConversations=new Map();let franziBusy=false,franziStatus='',franziLoading=false;
const franziHistory=()=>{if(!franziConversations.has(state.user.id))franziConversations.set(state.user.id,[]);return franziConversations.get(state.user.id);};
function franzi(){state.overlay='franzi';const history=franziHistory();modal('Franzi',`<div class="franzi-intro"><span class="franzi-avatar">${icon('franzi',33)}</span><div><strong>Ask me anything.</strong><p>${franziReady()?'AI is running on your device.':'Campus help · optional local AI'}</p></div></div>${!franziReady()?`<div class="franzi-setup"><p>For general questions, enable free AI on your device. One-time download of about 1 GB. Requires WebGPU; no API key.</p><button class="btn soft full" data-action="franzi-start" ${franziLoading?'disabled':''}>${franziLoading?'Loading AI…':'Enable local AI'}</button><small role="status">${e(franziStatus)}</small></div>`:''}<div class="franzi-messages" aria-live="polite">${history.map(m=>`<div class="franzi-message ${m.role}"><strong>${m.role==='user'?'You':'Franzi'}</strong><p>${e(m.content)}</p></div>`).join('')||'<p class="muted">How do I sell something? How do I meet people?</p>'}${franziBusy?'<p class="muted">Franzi is thinking…</p>':''}</div><form id="franzi-form"><label class="sr-only" for="franzi-question">Your question</label><div class="message-compose"><input id="franzi-question" name="question" placeholder="Ask Franzi…" maxlength="1000" required ${franziBusy?'disabled':''}><button class="btn primary" type="submit" ${franziBusy?'disabled':''}>${icon('send',18)}<span class="sr-only">Send</span></button></div></form><p class="form-hint">${franziReady()?'AI can make mistakes. It cannot read private chats or access live information.':'Campus help works without downloading AI.'}</p>`);const list=$('.franzi-messages');if(list)list.scrollTop=list.scrollHeight;if(!franziBusy)$('#franzi-question')?.focus();}
async function activateFranzi(){if(franziLoading)return;franziLoading=true;franziStatus='Preparing download…';franzi();try{await startFranziAI(status=>{franziStatus=status;const target=document.querySelector('.franzi-setup small');if(target)target.textContent=status;});franziStatus='';}catch(error){franziStatus=error.message;}finally{franziLoading=false;if(state.overlay==='franzi')franzi();}}
async function askFranzi(question){const history=franziHistory();if(franziBusy)return;franziBusy=true;history.push({role:'user',content:question});franzi();try{const answer=franziReady()?await franziAnswer(history,state.posts):campusAnswer(question,state.posts);history.push({role:'assistant',content:answer});}catch{history.push({role:'assistant',content:'The AI did not respond. Please try again.'});}finally{franziBusy=false;if(state.overlay==='franzi')franzi();}}

async function inbox() { state.overlay='inbox';if(!isDemo())state.chats=await api.chats();const chats=isDemo()?visibleDemoChats(state.chats,state.user.id,state.joined,state.posts):state.chats;modal('Messages',`<button class="btn outline full" data-action="people">${icon('plus',18)} New message</button><div class="chat-list">${chats.length?chats.map(c=>{const messages=state.messages[c.id]||[];return `<button class="chat-row" data-action="chat" data-id="${c.id}">${avatar(isDemo()?demoPerson(demoWorld,c.members?.find(id=>id!==state.user.id)):({name:c.title,color:'blue'}))}<span><strong>${e(chatTitle(c))}</strong><small>${e(messages.at(-1)?.body||'No messages yet')}</small></span>${icon('chevron',18)}</button>`;}).join(''):empty('No messages yet.','Choose someone from Contacts.',null)}</div>`); }
async function openChat(id) { if(!isDemo()&&!state.chats.find(c=>c.id===id))state.chats=await api.chats();const chat=state.chats.find(c=>c.id===id);if(isDemo()&&!visibleDemoChats(state.chats,state.user.id,state.joined,state.posts).some(c=>c.id===id)){toast('This conversation belongs to another profile.');return;}state.currentChat=id;state.overlay='chat';modal(chatTitle(chat),`<button class="text-link chat-back" data-action="inbox">${icon('chevron',20,'back-icon')} Messages</button><div class="chat-messages" id="chat-messages" aria-live="polite"></div><form id="message-form" class="message-form"><input name="body" required maxlength="2000" aria-label="Message" autocomplete="off" placeholder="Message …"><button class="icon-btn dark" type="submit" aria-label="Send message">${icon('send',20)}</button></form>`,{cls:'chat-modal'});await loadMessages(id);if(!isDemo())chatInterval=setInterval(()=>loadMessages(id),8000); }
async function loadMessages(id) { if(state.currentChat!==id)return;try{const messages=isDemo()?(state.messages[id]||[]):await api.messages(id);if(state.currentChat!==id)return;state.messages[id]=messages;const list=$('#chat-messages');if(!list)return;const nearBottom=list.scrollHeight-list.scrollTop-list.clientHeight<80;list.innerHTML=messages.length?messages.map(m=>`<div class="message ${m.author_id===state.user.id?'mine':''}"><p>${e(m.body)}</p><small>${e(isDemo()?demoPerson(demoWorld,m.author_id).name:m.author?.name||state.user.name)} · ${timeLabel(m.created_at)}</small></div>`).join(''):'<div class="chat-empty">'+icon('chat',42)+'<h3>No messages yet.</h3><p></p></div>';if(nearBottom)list.scrollTop=list.scrollHeight;}catch{toast('Could not load messages.');} }
async function groupChat(id) { const p=state.posts.find(x=>x.id===id);if(!p)return;if(isDemo()&&!joined(id)&&p.author_id!==state.user.id){toast('Join this activity first.');return;}if(!isDemo()){const chat=await api.rpc('activity_chat',{activity_id:id});return openChat(chat);}let chat=state.chats.find(c=>c.post_id===id);if(!chat){chat={id:crypto.randomUUID(),post_id:id,title:p.subtitle||p.title,created_at:new Date().toISOString(),color:'yellow'};state.chats.push(chat);state.messages[chat.id]=[];persist();}openChat(chat.id); }
function install(){if(deferredInstall){deferredInstall.prompt();deferredInstall.userChoice.then(()=>deferredInstall=null);return;}modal('Install app',`<p>Add FHV Friends to your home screen for an app-like experience.</p><div class="install-step"><strong>iPhone / iPad</strong><p>In Safari: Share → Add to Home Screen.</p></div><div class="install-step"><strong>Android</strong><p>In Chrome: Menu → Install app. An Android wrapper is also available.</p><a class="text-link" href="https://github.com/konstantinmantel/fhv-friends/actions/workflows/android.yml" target="_blank" rel="noopener noreferrer">Download Android wrapper</a></div><div class="install-step"><strong>Computer</strong><p>Choose the install icon in the Chrome or Edge address bar.</p></div>`);}

function postMenu(id) {const p=state.posts.find(x=>x.id===id);if(!p)return;const own=p.author_id===state.user.id;state.selected=id;state.overlay='post-menu';modal('Post options',`<div class="action-list"><button data-action="share" data-id="${id}">${icon('share')} Share post</button><button data-action="save" data-id="${id}">${icon('bookmark')} ${state.saved.includes(id)?'Remove from saved':'Save for later'}</button>${isOh()?`<button data-action="pin" data-id="${id}">${icon('pin')} ${p.pinned?'Unpin post':'Pin to feed'}</button>`:''}${own?`<button data-action="edit-post" data-id="${id}">${icon('settings')} Edit post</button><button class="danger" data-action="confirm-delete" data-id="${id}">${icon('trash')} Delete post</button>`:`<button data-action="report" data-id="${id}">${icon('flag')} Report post</button>`}</div>`); }
async function share(id) { const p=state.posts.find(x=>x.id===id);const url=new URL(location.href);url.hash=`post/${id}`; if(navigator.share){try{await navigator.share({title:p?.title||'FHV Friends',text:'Join me on FHV Friends.',url:url.href});}catch(ex){if(ex.name!=='AbortError')toast('Sharing is unavailable right now.');}}else{try{await navigator.clipboard.writeText(url.href);toast('Link copied.');}catch{modal('Share post',`<label>Copy link<input readonly value="${e(url.href)}"></label>`);}} }
function calendar(id) { const p=state.posts.find(x=>x.id===id);if(!p?.starts_at)return;const url=URL.createObjectURL(new Blob([makeICS(p)],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='fhv-friends.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Calendar event downloaded.'); }
async function loadLive(user) { state.loading=true;state.mode='live';render();try { const [profile,role,posts,userState,memberships]=await Promise.all([api.profile(user.id),api.role(),api.posts(),api.state(user.id),api.memberships()]);state.user={...profile,id:user.id,role};state.posts=posts.map(p=>({...p,price:Number(p.price||0),likes:Number(p.likes||0)}));Object.assign(state,userState);const counts={};memberships.forEach(m=>counts[m.post_id]=(counts[m.post_id]||0)+1);state.posts.forEach(p=>p.join_count=counts[p.id]||0); }catch(error){state.posts=[];toast(error.message);}finally{state.loading=false;render();} }
async function invitePeople(id) { state.overlay='invite-people';const people=isDemo()?demoWorld.profiles:await api.people();modal('Invite people',`<p class="modal-lead"></p><div class="people-list">${people.filter(p=>p.id!==state.user.id).map(p=>`<div class="people-row">${avatar(p)}<span><strong>${e(p.name)}</strong><small>${e(p.course||'FHV Community')}</small></span><button class="btn soft small" data-action="send-invite" data-post="${id}" data-id="${p.id}">Invite</button></div>`).join('')}</div>`); }
function imageEditor(kind,data){return `<div class="photo-editor"><div id="${kind}-photo-preview" class="photo-preview ${kind==='profile'?'round':''}">${safeImage(data)?`<img src="${e(safeImage(data))}" alt="Selected photo">`:icon(kind==='profile'?'user':'plus',26)}</div><div><label class="photo-label">${kind==='profile'?'Profile photo':'Photo (optional)'}<input id="${kind}-photo" name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="text-link photo-remove" type="button" data-action="remove-photo" data-kind="${kind}">Remove photo</button><small>JPG, PNG or WebP · up to 8 MB</small></div></div>`;}
function removePhoto(kind){if(kind==='profile')state.profilePhotoDraft=null;else state.postPhotoDraft=null;const box=$(`#${kind}-photo-preview`);if(box)box.innerHTML=icon(kind==='profile'?'user':'plus',26);const file=$(`#${kind}-photo`);if(file)file.value='';}
async function preparePhoto(file,maxLength){
 if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Choose a JPG, PNG or WebP photo.');
 if(file.size>8*1024*1024)throw new Error('Photos can be up to 8 MB.');
 const url=URL.createObjectURL(file);
 try{
  const image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('Could not open this photo.'));i.src=url;});
  const canvas=document.createElement('canvas');let edge=maxLength<=120000?384:960;
  for(let attempt=0;attempt<5;attempt++){
   const ratio=Math.min(1,edge/Math.max(image.naturalWidth,image.naturalHeight));canvas.width=Math.max(1,Math.round(image.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(image.naturalHeight*ratio));
   const context=canvas.getContext('2d');context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);
   const value=canvas.toDataURL('image/jpeg',.78-attempt*.08);if(safeImage(value,maxLength))return value;edge=Math.round(edge*.8);
  }
  throw new Error('Please choose a smaller photo.');
 }finally{URL.revokeObjectURL(url);}
}
function testAccounts(){if(!isDemo())return;state.overlay='test-accounts';modal('Switch profile',`<div class="test-accounts">${demoWorld.profiles.map(p=>`<button class="test-account ${p.id===state.user.id?'current':''}" data-action="switch-account" data-id="${p.id}">${avatar(p)}<span><strong>${e(p.name)}</strong>${p.course?`<small>${e(p.course)}</small>`:''}</span>${p.id===state.user.id?icon('check',18):icon('chevron',18)}</button>`).join('')}</div>`);}
function switchAccount(id){
 if(!isDemo()||!demoWorld.profiles.some(p=>p.id===id))return;
 persist();const account=demoWorld.accounts[id]||emptyDemoAccount();state.user={...demoPerson(demoWorld,id)};
 Object.assign(state,{joined:account.joined,saved:account.saved,liked:account.liked,invitations:account.invitations});
 state.posts=hydrateDemoPosts(demoWorld);try{sessionStorage.setItem('fhv-demo-active',id);}catch{}
 closeModal();render();toast(`${state.user.name} selected.`);
}
function chatTitle(chat){if(!chat)return 'Messages';if(!isDemo()||chat.post_id)return chat.title||'Group chat';const other=chat.members?.find(id=>id!==state.user.id);return other?demoPerson(demoWorld,other).name:chat.title||'Chat';}

